def parse_blocks(md_text, smart=True, id_prefix="", shift=0, auto_ids=True, number_sections=False, number_offset=None):
    lines = md_text.splitlines()
    blocks = []
    i=0
    existing_ids = set()
    while i < len(lines):
        line = lines[i]
        if not line.strip():
            i+=1
            continue
        m = re.match(r'^(#{1,6})\\s+(.*)$', line)
        if m:
            level = len(m.group(1)) + shift
            if level>6: level=6
            if level<1: level=1
            content_raw = m.group(2).strip()
            attr_id=None
            classes=[]
            attr_match = re.search(r'\\s*\\{([^}]*)\\}\\s*$', content_raw)
            if attr_match:
                attr_str = attr_match.group(1)
                content_raw = content_raw[:attr_match.start()].strip()
                for token in re.findall(r'#\\S+|\\.\\S+|\\S+=\\S+|\\S+', attr_str):
                    if token.startswith("#"):
                        attr_id = token[1:]
                    elif token.startswith("."):
                        classes.append(token[1:])
            if not attr_id and auto_ids:
                plain = re.sub(r'[*_`\\[\\]]', '', content_raw)
                attr_id = generate_id(plain, existing_ids, prefix=id_prefix)
            elif attr_id:
                if id_prefix and not attr_id.startswith(id_prefix):
                    attr_id = id_prefix + attr_id
                base=attr_id
                counter=1
                while attr_id in existing_ids:
                    attr_id = f"{base}-{counter}"
                    counter+=1
                existing_ids.add(attr_id)
            blocks.append({"type":"header","level":level,"content":content_raw,"id":attr_id,"classes":classes})
            i+=1
            continue
        if re.match(r'^\\s*(\\*\\*\\*|---|___)\\s*$', line):
            if line.strip() in ("***","---","___"):
                blocks.append({"type":"hr"})
                i+=1
                continue
        m = re.match(r'^```(\\w*)\\s*$', line)
        if m:
            lang = m.group(1)
            code_lines=[]
            i+=1
            while i < len(lines) and not re.match(r'^```\\s*$', lines[i]):
                code_lines.append(lines[i])
                i+=1
            if i < len(lines):
                i+=1
            blocks.append({"type":"code","lang":lang,"text":"\\n".join(code_lines)})
            continue
        if line.startswith("    "):
            code_lines=[]
            while i < len(lines) and (lines[i].startswith("    ") or not lines[i].strip()):
                if lines[i].startswith("    "):
                    code_lines.append(lines[i][4:])
                else:
                    code_lines.append("")
                i+=1
            blocks.append({"type":"code","lang":"","text":"\\n".join(code_lines).strip("\\n"),"indented":True})
            continue
        if line.startswith(">"):
            bq_lines=[]
            while i < len(lines) and lines[i].startswith(">"):
                bq_lines.append(lines[i][1:].lstrip())
                i+=1
            blocks.append({"type":"blockquote","text":"\\n".join(bq_lines)})
            continue
        if re.match(r'^\\s*\\d+\\.\\s+.*$', line):
            items=[]
            while i < len(lines) and re.match(r'^\\s*\\d+\\.\\s+.*$', lines[i]):
                m2 = re.match(r'^\\s*\\d+\\.\\s+(.*)$', lines[i])
                items.append(m2.group(1))
                i+=1
            blocks.append({"type":"ol","items":items})
            continue
        if re.match(r'^\\s*[-*+]\\s+.*$', line):
            # Check task list first
            if re.match(r'^\\s*-\\s+\\[[ xX]\\]\\s+.*$', line):
                items=[]
                while i < len(lines) and re.match(r'^\\s*-\\s+\\[[ xX]\\]\\s+.*$', lines[i]):
                    m2 = re.match(r'^\\s*-\\s+\\[([ xX])\\]\\s+(.*)$', lines[i])
                    checked = m2.group(1).lower() == 'x'
                    items.append((m2.group(2), checked))
                    i+=1
                blocks.append({"type":"tasklist","items":items})
                continue
            items=[]
            while i < len(lines) and re.match(r'^\\s*[-*+]\\s+.*$', lines[i]):
                m2 = re.match(r'^\\s*[-*+]\\s+(.*)$', lines[i])
                items.append(m2.group(1))
                i+=1
            blocks.append({"type":"ul","items":items})
            continue
        if "|" in line and i+1 < len(lines) and re.match(r'^\\s*\\|?(\\s*[-:]+\\s*\\|)+\\s*[-:]+\\s*\\|?\\s*$', lines[i+1]):
            header = line
            sep = lines[i+1]
            rows=[]
            i+=2
            while i < len(lines) and "|" in lines[i]:
                rows.append(lines[i])
                i+=1
            def split_row(r):
                r=r.strip()
                if r.startswith("|"):
                    r=r[1:]
                if r.endswith("|"):
                    r=r[:-1]
                return [c.strip() for c in r.split("|")]
            headers = split_row(header)
            data_rows = [split_row(r) for r in rows]
            blocks.append({"type":"table","headers":headers,"rows":data_rows})
            continue
        # Paragraph
        para_lines=[]
        while i < len(lines) and lines[i].strip() and not re.match(r'^(#{1,6})\\s+.*$', lines[i]) and not re.match(r'^\\s*[-*+]\\s+.*$', lines[i]) and not re.match(r'^\\s*\\d+\\.\\s+.*$', lines[i]) and not lines[i].startswith(">") and not lines[i].startswith("    ") and not re.match(r'^```', lines[i]) and not ("|" in lines[i] and i+1 < len(lines) and re.match(r'^\\s*\\|?(\\s*[-:]+\\s*\\|)+\\s*[-:]+\\s*\\|?\\s*$', lines[i+1])):
            para_lines.append(lines[i])
            i+=1
        para_text = " ".join(para_lines).strip()
        if para_text:
            if re.match(r'^\\s*!\\[.*\\]\\(.*\\)\\s*$', para_text):
                blocks.append({"type":"para","text":para_text,"is_image_only":True})
            else:
                blocks.append({"type":"para","text":para_text})
        if not para_lines:
            i+=1
    return blocks

def md_to_html(md_text, smart=True, id_prefix="", shift=0, auto_ids=True, number_sections=False, number_offset=None, math_mode="none", is_gfm=False):
