                counters[k]=0
            number_str=""
            data_number=""
            if number_sections:
                nums=[]
                for k in range(lvl):
                    c = counters[k]
                    if number_offset and k==0:
                        c += number_offset[0]
                    if c>0:
                        nums.append(str(c))
                number_str = ".".join(nums)
