            if number_sections and number_str:
                html_parts.append(f'<h{lvl} data-number="{html_module.escape(data_number)}"{id_attr}><span class="header-section-number">{html_module.escape(number_str)}</span> {content_html}</h{lvl}>')
            else:
                if class_attr and id_attr:
                    html_parts.append(f'<h{lvl}{class_attr}{id_attr}>{content_html}</h{lvl}>')
                elif id_attr:
                    html_parts.append(f'<h{lvl}{id_attr}>{content_html}</h{lvl}>')
                elif class_attr:
                    html_parts.append(f'<h{lvl}{class_attr}>{content_html}</h{lvl}>')
                else:
                    if b["id"]:
