            for idx,it in enumerate(b["items"],1):
                it2 = re.sub(r'\\*([^*]+)\\*', r'\\1', it)
                lines.append(f"{idx}.  {it2}")
            lines.append("")
        elif b["type"]=="code":
            for cl in b["text"].splitlines():
                lines.append(f"    {cl}")
