            txt = re.sub(r'\\*([^*]+)\\*', r'\\1', txt)
            lines.append(f"  {txt}")
            lines.append("")
        elif b["type"]=="table":
            hdrs = b["headers"]
            rows = b["rows"]
            lines.append("  " + "   ".join(hdrs))
            lines.append("  " + "   ".join(["---" for _ in hdrs]))
            for r in rows:
                lines.append("  " + "   ".join(r))
            lines.append("")
        elif b["type"]=="hr":
            lines.append("----------------------------------------")
            lines.append("")
    text = "\\n".join(lines).strip() + "\\n" if lines else "\\n"
    if wrap == "none":
        pass
    elif wrap == "auto" and columns:
        wrapped=[]
        for line in text.splitlines():
            if len(line) > columns:
                wrapped.extend(textwrap.wrap(line, width=columns))
            else:
                wrapped.append(line)
        text = "\\n".join(wrapped) + "\\n" if wrapped else "\\n"
    return text

def md_to_latex(md_text, smart=True):
    blocks = parse_blocks(md_text, smart=smart)
    out=[]
    for b in blocks:
