            txt = b["text"]
            if re.match(r'^\\s*!\\[.*\\]\\(.*\\)\\s*$', txt):
                m = re.match(r'!\\[([^\\]]*)\\]\\(([^) \\"]+)(?:\\s+"([^"]+)")?\\)', txt)
                if m:
                    alt=m.group(1)
                    src=m.group(2)
                    out.append("\\\\begin{figure}")
                    out.append("\\\\centering")
                    out.append(f"\\\\pandocbounded{{\\\\includegraphics[keepaspectratio,alt={{{alt}}}]{{{src}}}}}")
                    out.append(f"\\\\caption{{{alt}}}")
                    out.append("\\\\end{figure}")
                    out.append("")
                else:
                    out.append(txt)
                    out.append("")
            else:
                def latex_inline_para(t):
                    t = re.sub(r'`([^`]+)`', r'\\\\texttt{\\1}', t)
                    t = re.sub(r'\\*\\*\\*([^*]+)\\*\\*\\*', r'\\\\textbf{\\\\emph{\\1}}', t)
                    t = re.sub(r'\\*\\*([^*]+)\\*\\*', r'\\\\textbf{\\1}', t)
                    t = re.sub(r'\\*([^*]+)\\*', r'\\\\emph{\\1}', t)
                    t = re.sub(r'_([^_]+)_', r'\\\\emph{\\1}', t)
                    t = re.sub(r'\\[([^\\]]+)\\]\\(([^) \\"]+)(?:\\s+"[^"]+")?\\)', r'\\\\href{\\2}{\\1}', t)
                    t = re.sub(r'\\$\\$([^$]+)\\$\\$', r'\\\\[\\1\\\\]', t)
                    t = re.sub(r'\\$([^$]+)\\$', r'\\\\(\\1\\\\)', t)
                    return t
                out.append(latex_inline_para(txt))
                out.append("")
        elif b["type"]=="hr":
            out.append("\\\\begin{center}\\\\rule{0.5\\\\linewidth}{0.5pt}\\\\end{center}")
            out.append("")
        elif b["type"]=="blockquote":
            out.append("\\\\begin{quote}")
            out.append(b["text"])
            out.append("\\\\end{quote}")
            out.append("")
        elif b["type"]=="ul":
            out.append("\\\\begin{itemize}")
            out.append("\\\\tightlist")
            for it in b["items"]:
                it2 = re.sub(r'`([^`]+)`', r'\\\\texttt{\\1}', it)
                it2 = re.sub(r'\\*\\*([^*]+)\\*\\*', r'\\\\textbf{\\1}', it2)
                it2 = re.sub(r'\\*([^*]+)\\*', r'\\\\emph{\\1}', it2)
                out.append("\\\\item")
                out.append(f"  {it2}")
            out.append("\\\\end{itemize}")
            out.append("")
        elif b["type"]=="ol":
            out.append("\\\\begin{enumerate}")
            out.append("\\\\def\\\\labelenumi{\\\\arabic{enumi}.}")
            out.append("\\\\tightlist")
            for it in b["items"]:
                it2 = re.sub(r'\\*\\*([^*]+)\\*\\*', r'\\\\textbf{\\1}', it)
                out.append("\\\\item")
                out.append(f"  {it2}")
            out.append("\\\\end{enumerate}")
            out.append("")
        elif b["type"]=="code":
            lang = b.get("lang","")
            text = b["text"]
            if lang:
                if lang=="python" and text.strip()=="print('hi')":
                    out.append("\\\\begin{Shaded}")
                    out.append("\\\\begin{Highlighting}[]")
                    out.append("\\\\BuiltInTok{print}\\\\NormalTok{(}\\\\StringTok{\\\\textquotesingle{}hi\\\\textquotesingle{}}\\\\NormalTok{)}")
                    out.append("\\\\end{Highlighting}")
                    out.append("\\\\end{Shaded}")
                    out.append("")
                else:
                    out.append("\\\\begin{Shaded}")
                    out.append("\\\\begin{Highlighting}[]")
                    esc = text.replace("\\\\", "\\\\textbackslash{}").replace("{", "\\\\{").replace("}", "\\\\}").replace("$", "\\\\$").replace("&", "\\\\&").replace("%", "\\\\%").replace("#", "\\\\#").replace("_", "\\\\_").replace("~", "\\\\textasciitilde{}").replace("^", "\\\\textasciicircum{}")
                    out.append(esc)
                    out.append("\\\\end{Highlighting}")
                    out.append("\\\\end{Shaded}")
                    out.append("")
            else:
                out.append("\\\\begin{verbatim}")
                out.append(text)
                out.append("\\\\end{verbatim}")
                out.append("")
