            hdrs = b["headers"]
            rows = b["rows"]
            out.append("{\\\\def\\\\LTcaptype{none} % do not increment counter")
            out.append("\\\\begin{longtable}[]{@{}" + "l"*len(hdrs) + "@{}}")
            out.append("\\\\toprule\\\\noalign{}")
            out.append(" & ".join(hdrs) + " \\\\")
            out.append("\\\\midrule\\\\noalign{}")
            out.append("\\\\endhead")
            out.append("\\\\bottomrule\\\\noalign{}")
            out.append("\\\\endlastfoot")
            for r in rows:
                out.append(" & ".join(r) + " \\\\")
            out.append("\\\\end{longtable}")
            out.append("}")
            out.append("")
    return "\\n".join(out).strip() + ("\\n" if out else "\\n")

def html_to_markdown(html_text):
    text = html_text
    text = re.sub(r'<h1[^>]*>(.*?)</h1>', lambda m: f"# {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<h2[^>]*>(.*?)</h2>', lambda m: f"## {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<h3[^>]*>(.*?)</h3>', lambda m: f"### {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\\n", text, flags=re.DOTALL|re.IGNORECASE)
    def inline_html_to_md(s):
        s = re.sub(r'<em[^>]*>(.*?)</em>', r'*\\1*', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<strong[^>]*>(.*?)</strong>', r'**\\1**', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<code[^>]*>(.*?)</code>', r'`\\1`', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', r'[\\2](\\1)', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<[^>]+>', '', s)
        s = html_module.unescape(s)
        return s.strip()
    text = re.sub(r'<p[^>]*>(.*?)</p>', lambda m: f"{inline_html_to_md(m.group(1))}\\n\\n", text, flags=re.DOTALL|re.IGNORECASE)
    def repl_ul(m):
        inner = m.group(1)
        items = re.findall(r'<li[^>]*>(.*?)</li>', inner, flags=re.DOTALL|re.IGNORECASE)
        return "\\n".join([f"- {inline_html_to_md(it)}" for it in items]) + "\\n\\n"
    text = re.sub(r'<ul[^>]*>(.*?)</ul>', repl_ul, text, flags=re.DOTALL|re.IGNORECASE)
    def repl_ol(m):
        inner = m.group(1)
        items = re.findall(r'<li[^>]*>(.*?)</li>', inner, flags=re.DOTALL|re.IGNORECASE)
        return "\\n".join([f"{idx}. {inline_html_to_md(it)}" for idx,it in enumerate(items,1)]) + "\\n\\n"
    text = re.sub(r'<ol[^>]*>(.*?)</ol>', repl_ol, text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<blockquote[^>]*>(.*?)</blockquote>', lambda m: "> " + re.sub(r'<[^>]+>', '', m.group(1)).strip().replace("\\n", "\\n> ") + "\\n\\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<[^>]+>', '', text)
    text = html_module.unescape(text)
    text = re.sub(r'\\n{3,}', '\\n\\n', text)
    return text.strip() + "\\n" if text.strip() else "\\n"

def csv_to_html(csv_text):
    import csv as csv_module, io
    f = io.StringIO(csv_text)
    reader = csv_module.reader(f)
    rows = list(reader)
    if not rows:
        return ""
    html_parts = ['<table>', '<thead>', '<tr>']
    headers = rows[0]
    for h in headers:
        html_parts.append(f'<th>{html_module.escape(h)}</th>')
    html_parts.append('</tr>')
    html_parts.append('</thead>')
    html_parts.append('<tbody>')
    for r in rows[1:]:
        html_parts.append('<tr>')
        for cell in r:
            html_parts.append(f'<td>{html_module.escape(cell)}</td>')
        html_parts.append('</tr>')
    html_parts.append('</tbody>')
    html_parts.append('</table>')
    return "\\n".join(html_parts) + "\\n"

def json_to_markdown(json_text):
    try:
        data = json.loads(json_text)
        blocks = data.get("blocks", [])
        md_lines=[]
        for blk in blocks:
            t = blk.get("t")
            c = blk.get("c")
            if t == "Para":
                txt = ""
                for inline in c:
                    if inline["t"] == "Str":
                        txt += inline["c"] + " "
                    elif inline["t"] == "Space":
                        txt += " "
                    elif inline["t"] == "Emph":
                        inner = "".join([x["c"] for x in inline["c"] if x["t"]=="Str"])
                        txt += f"*{inner}* "
                    elif inline["t"] == "Strong":
                        inner = "".join([x["c"] for x in inline["c"] if x["t"]=="Str"])
                        txt += f"**{inner}** "
                md_lines.append(txt.strip())
                md_lines.append("")
            elif t == "Header":
                level = c[0]
                inlines = c[2]
                txt = "".join([x["c"] for x in inlines if x["t"]=="Str"])
                md_lines.append("#"*level + " " + txt)
                md_lines.append("")
        return "\\n".join(md_lines).strip() + "\\n" if md_lines else "\\n"
    except Exception:
        return json_text

def md_to_json(md_text):
