    for b in parsed:
        if b["type"]=="header":
            level = b["level"]
            text = b["content"]
            inlines=[]
            for word in text.split():
                inlines.append({"t":"Str","c":word})
                inlines.append({"t":"Space"})
            if inlines and inlines[-1]["t"]=="Space":
                inlines.pop()
            blocks.append({"t":"Header","c":[level, [b["id"] or "", [], []], inlines]})
        elif b["type"]=="para":
            txt = b["text"]
            clean = re.sub(r'\\*([^*]+)\\*', r'\\1', txt)
            clean = re.sub(r'\\*\\*([^*]+)\\*\\*', r'\\1', clean)
            words = clean.split()
            inlines=[]
            for w in words:
                inlines.append({"t":"Str","c":w})
                inlines.append({"t":"Space"})
            if inlines and inlines[-1]["t"]=="Space":
                inlines.pop()
            blocks.append({"t":"Para","c": inlines})
        else:
            txt = b.get("text","") or str(b)
            inlines=[{"t":"Str","c":w} for w in txt.split()]
            inlines2=[]
            for idx, inl in enumerate(inlines):
                inlines2.append(inl)
                if idx < len(inlines)-1:
                    inlines2.append({"t":"Space"})
            blocks.append({"t":"Para","c": inlines2})
    data = {"pandoc-api-version":[1,23,1,2],"meta":{},"blocks":blocks}
    return json.dumps(data)

def md_to_native(md_text):
    parsed = parse_blocks(md_text, smart=False)
    parts=[]
    for b in parsed:
        if b["type"]=="header":
            lvl = b["level"]
            txt = b["content"]
            txt_esc = txt.replace('"', '\\\\"')
            parts.append(f'Header {lvl} ( "{b["id"] or txt.lower()}" , [] , [] ) [ Str "{txt_esc}" ]')
        elif b["type"]=="para":
            txt = b["text"]
            words = txt.split()
            inlines=[]
            for w in words:
                w_clean = re.sub(r'\\*([^*]+)\\*', r'\\1', w)
