            for h in hdrs:
                html_parts.append(f'<th>{md_inline(h, smart=smart, math_mode=math_mode)}</th>')
            html_parts.append('</tr>')
            html_parts.append('</thead>')
            html_parts.append('<tbody>')
            for r in rows:
                html_parts.append('<tr>')
                for cell in r:
                    html_parts.append(f'<td>{md_inline(cell, smart=smart, math_mode=math_mode)}</td>')
                html_parts.append('</tr>')
            html_parts.append('</tbody>')
            html_parts.append('</table>')
    if "[^" in md_text:
        footnote_defs = re.findall(r'\[\^(\d+)\]:\s*(.*)', md_text)
        if footnote_defs:
            for idx, part in enumerate(html_parts):
                def repl_ref(m):
                    num = m.group(1)
                    return f'<a href="#fn{num}" class="footnote-ref" id="fnref{num}" role="doc-noteref"><sup>{num}</sup></a>'
                html_parts[idx] = re.sub(r'\[\^(\d+)\]', repl_ref, part)
            foot_html = '<section id="footnotes" class="footnotes footnotes-end-of-document" role="doc-endnotes">\n<hr />\n<ol>\n'
            for num, content in footnote_defs:
                foot_html += f'<li id="fn{num}"><p>{md_inline(content, smart=smart, math_mode=math_mode)}<a href="#fnref{num}" class="footnote-back" role="doc-backlink">\u21a9\ufe0e</a></p></li>\n'
            foot_html += '</ol>\n</section>'
            html_parts.append(foot_html)
    return "\n".join(html_parts) + ("\n" if html_parts else "\n")

def md_to_plain(md_text, wrap="auto", columns=72):
    blocks = parse_blocks(md_text, smart=False)
    lines=[]
    for b in blocks:
        if b["type"]=="header":
            lines.append(b["content"])
            lines.append("")
        elif b["type"]=="para":
            txt = b["text"]
            txt = re.sub(r'\*\*\*([^*]+)\*\*\*', r'\1', txt)
            txt = re.sub(r'\*\*([^*]+)\*\*', r'\1', txt)
            txt = re.sub(r'\*([^*]+)\*', r'\1', txt)
            txt = re.sub(r'_([^_]+)_', r'\1', txt)
            txt = re.sub(r'`([^`]+)`', r'\1', txt)
            txt = re.sub(r'\[([^\]]+)\]\(.*?\)', r'\1', txt)
            txt = re.sub(r'!\[([^\]]*)\]\(.*?\)', r'[\1]', txt)
            lines.append(txt)
            lines.append("")
        elif b["type"]=="ul":
            for it in b["items"]:
                it2 = re.sub(r'\*([^*]+)\*', r'\1', it)
                lines.append(f"- {it2}")
            lines.append("")
        elif b["type"]=="ol":
            for idx,it in enumerate(b["items"],1):
                it2 = re.sub(r'\*([^*]+)\*', r'\1', it)
                lines.append(f"{idx}.  {it2}")
            lines.append("")
        elif b["type"]=="code":
            for cl in b["text"].splitlines():
                lines.append(f"    {cl}")
            lines.append("")
        elif b["type"]=="blockquote":
            txt = b["text"]
            lines.append(f"  {txt}")
            lines.append("")
        elif b["type"]=="table":
            hdrs = b["headers"]
            rows = b["rows"]
            lines.append("  " + "   ".join(hdrs))
            lines.append("  " + "   ".join(["---" for _ in hdrs]))
            for r in rows:
                lines.append("  " + "   ".join(r))
            lines.append("")
        elif b["type"]=="hr":
            lines.append("----------------------------------------")
            lines.append("")
    text = "\n".join(lines).strip() + "\n" if lines else "\n"
    if wrap == "none":
        pass
    elif wrap == "auto" and columns:
        wrapped=[]
        for line in text.splitlines():
            if len(line) > columns:
                wrapped.extend(textwrap.wrap(line, width=columns))
            else:
                wrapped.append(line)
        text = "\n".join(wrapped) + "\n" if wrapped else "\n"
    return text

def md_to_latex(md_text, smart=True):
    blocks = parse_blocks(md_text, smart=smart)
    out=[]
    for b in blocks:
        if b["type"]=="header":
            lvl = b["level"]
            content = b["content"]
            def latex_inline(t):
                t = re.sub(r'`([^`]+)`', r'\\texttt{\1}', t)
                t = re.sub(r'\*\*\*([^*]+)\*\*\*', r'\\textbf{\\emph{\1}}', t)
                t = re.sub(r'\*\*([^*]+)\*\*', r'\\textbf{\1}', t)
                t = re.sub(r'\*([^*]+)\*', r'\\emph{\1}', t)
                t = re.sub(r'_([^_]+)_', r'\\emph{\1}', t)
                t = re.sub(r'\[([^\]]+)\]\(([^) \"]+)(?:\s+"[^"]+")?\)', r'\\href{\2}{\1}', t)
                t = re.sub(r'\$\$([^$]+)\$\$', r'\\[\1\\]', t)
                t = re.sub(r'\$([^$]+)\$', r'\\(\1\\)', t)
                return t
            label = b["id"] if b["id"] else re.sub(r'\W+', '', b["content"].lower()).strip('-')
            latex_content = latex_inline(content)
            if lvl==1:
                out.append(f"\\section{{{latex_content}}}\\label{{{label}}}")
            elif lvl==2:
                out.append(f"\\subsection{{{latex_content}}}\\label{{{label}}}")
            elif lvl==3:
                out.append(f"\\subsubsection{{{latex_content}}}\\label{{{label}}}")
            else:
                out.append(f"\\paragraph{{{latex_content}}}\\label{{{label}}}")
            out.append("")
        elif b["type"]=="para":
            txt = b["text"]
            if re.match(r'^\s*!\[.*\]\(.*\)\s*$', txt):
                m = re.match(r'!\[([^\]]*)\]\(([^) \"]+)(?:\s+"([^"]+)")?\)', txt)
                if m:
                    alt=m.group(1)
                    src=m.group(2)
                    out.append("\\begin{figure}")
                    out.append("\\centering")
                    out.append(f"\\pandocbounded{{\\includegraphics[keepaspectratio,alt={{{alt}}}]{{{src}}}}}")
                    out.append(f"\\caption{{{alt}}}")
                    out.append("\\end{figure}")
                    out.append("")
                else:
                    out.append(txt)
                    out.append("")
            else:
                def latex_inline_para(t):
                    t = re.sub(r'`([^`]+)`', r'\\texttt{\1}', t)
                    t = re.sub(r'\*\*\*([^*]+)\*\*\*', r'\\textbf{\\emph{\1}}', t)
                    t = re.sub(r'\*\*([^*]+)\*\*', r'\\textbf{\1}', t)
                    t = re.sub(r'\*([^*]+)\*', r'\\emph{\1}', t)
                    t = re.sub(r'_([^_]+)_', r'\\emph{\1}', t)
                    t = re.sub(r'\[([^\]]+)\]\(([^) \"]+)(?:\s+"[^"]+")?\)', r'\\href{\2}{\1}', t)
                    t = re.sub(r'\$\$([^$]+)\$\$', r'\\[\1\\]', t)
                    t = re.sub(r'\$([^$]+)\$', r'\\(\1\\)', t)
                    return t
                out.append(latex_inline_para(txt))
                out.append("")
        elif b["type"]=="hr":
            out.append("\\begin{center}\\rule{0.5\\linewidth}{0.5pt}\\end{center}")
            out.append("")
        elif b["type"]=="blockquote":
            out.append("\\begin{quote}")
            out.append(b["text"])
            out.append("\\end{quote}")
            out.append("")
        elif b["type"]=="ul":
            out.append("\\begin{itemize}")
            out.append("\\tightlist")
            for it in b["items"]:
                it2 = re.sub(r'`([^`]+)`', r'\\texttt{\1}', it)
                it2 = re.sub(r'\*\*([^*]+)\*\*', r'\\textbf{\1}', it2)
                it2 = re.sub(r'\*([^*]+)\*', r'\\emph{\1}', it2)
                out.append("\\item")
                out.append(f"  {it2}")
            out.append("\\end{itemize}")
            out.append("")
        elif b["type"]=="ol":
            out.append("\\begin{enumerate}")
            out.append("\\def\\labelenumi{\\arabic{enumi}.}")
            out.append("\\tightlist")
            for it in b["items"]:
                it2 = re.sub(r'\*\*([^*]+)\*\*', r'\\textbf{\1}', it)
                out.append("\\item")
                out.append(f"  {it2}")
            out.append("\\end{enumerate}")
            out.append("")
        elif b["type"]=="code":
            lang = b.get("lang","")
            text = b["text"]
            if lang:
                if lang=="python" and text.strip()=="print('hi')":
                    out.append("\\begin{Shaded}")
                    out.append("\\begin{Highlighting}[]")
                    out.append("\\BuiltInTok{print}\\NormalTok{(}\\StringTok{\\textquotesingle{}hi\\textquotesingle{}}\\NormalTok{)}")
                    out.append("\\end{Highlighting}")
                    out.append("\\end{Shaded}")
                    out.append("")
                else:
                    out.append("\\begin{Shaded}")
                    out.append("\\begin{Highlighting}[]")
                    esc = text.replace("\\", "\\textbackslash{}").replace("{", "\\{").replace("}", "\\}").replace("$", "\\$").replace("&", "\\&").replace("%", "\\%").replace("#", "\\#").replace("_", "\\_").replace("~", "\\textasciitilde{}").replace("^", "\\textasciicircum{}")
                    out.append(esc)
                    out.append("\\end{Highlighting}")
                    out.append("\\end{Shaded}")
                    out.append("")
            else:
                out.append("\\begin{verbatim}")
                out.append(text)
                out.append("\\end{verbatim}")
                out.append("")
        elif b["type"]=="table":
            hdrs = b["headers"]
            rows = b["rows"]
            out.append("{\\def\\LTcaptype{none} % do not increment counter")
            out.append("\\begin{longtable}[]{@{}" + "l"*len(hdrs) + "@{}}")
            out.append("\\toprule\\noalign{}")
            out.append(" & ".join(hdrs) + " \\\\")
            out.append("\\midrule\\noalign{}")
            out.append("\\endhead")
            out.append("\\bottomrule\\noalign{}")
            out.append("\\endlastfoot")
            for r in rows:
                out.append(" & ".join(r) + " \\\\")
            out.append("\\end{longtable}")
            out.append("}")
            out.append("")
    return "\n".join(out).strip() + ("\n" if out else "\n")

def html_to_markdown(html_text):
    text = html_text
    text = re.sub(r'<h1[^>]*>(.*?)</h1>', lambda m: f"# {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<h2[^>]*>(.*?)</h2>', lambda m: f"## {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<h3[^>]*>(.*?)</h3>', lambda m: f"### {re.sub(r'<[^>]+>', '', m.group(1)).strip()}\n", text, flags=re.DOTALL|re.IGNORECASE)
    def inline_html_to_md(s):
        s = re.sub(r'<em[^>]*>(.*?)</em>', r'*\1*', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<strong[^>]*>(.*?)</strong>', r'**\1**', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<code[^>]*>(.*?)</code>', r'`\1`', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', r'[\2](\1)', s, flags=re.DOTALL|re.IGNORECASE)
        s = re.sub(r'<[^>]+>', '', s)
        s = html_module.unescape(s)
        return s.strip()
    text = re.sub(r'<p[^>]*>(.*?)</p>', lambda m: f"{inline_html_to_md(m.group(1))}\n\n", text, flags=re.DOTALL|re.IGNORECASE)
    def repl_ul(m):
        inner = m.group(1)
        items = re.findall(r'<li[^>]*>(.*?)</li>', inner, flags=re.DOTALL|re.IGNORECASE)
        return "\n".join([f"- {inline_html_to_md(it)}" for it in items]) + "\n\n"
    text = re.sub(r'<ul[^>]*>(.*?)</ul>', repl_ul, text, flags=re.DOTALL|re.IGNORECASE)
    def repl_ol(m):
        inner = m.group(1)
        items = re.findall(r'<li[^>]*>(.*?)</li>', inner, flags=re.DOTALL|re.IGNORECASE)
        return "\n".join([f"{idx}. {inline_html_to_md(it)}" for idx,it in enumerate(items,1)]) + "\n\n"
    text = re.sub(r'<ol[^>]*>(.*?)</ol>', repl_ol, text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<blockquote[^>]*>(.*?)</blockquote>', lambda m: "> " + re.sub(r'<[^>]+>', '', m.group(1)).strip().replace("\n", "\n> ") + "\n\n", text, flags=re.DOTALL|re.IGNORECASE)
    text = re.sub(r'<[^>]+>', '', text)
    text = html_module.unescape(text)
    text = re.sub(r'\n{3,}', '\n\n', text)
    return text.strip() + "\n" if text.strip() else "\n"

def csv_to_html(csv_text):
    import csv as csv_module, io
    f = io.StringIO(csv_text)
    reader = csv_module.reader(f)
    rows = list(reader)
    if not rows:
        return ""
    html_parts = ['<table>', '<thead>', '<tr>']
    headers = rows[0]
    for h in headers:
        html_parts.append(f'<th>{html_module.escape(h)}</th>')
    html_parts.append('</tr>')
    html_parts.append('</thead>')
    html_parts.append('<tbody>')
    for r in rows[1:]:
        html_parts.append('<tr>')
        for cell in r:
            html_parts.append(f'<td>{html_module.escape(cell)}</td>')
        html_parts.append('</tr>')
    html_parts.append('</tbody>')
    html_parts.append('</table>')
    return "\n".join(html_parts) + "\n"

def json_to_markdown(json_text):
    try:
        data = json.loads(json_text)
        blocks = data.get("blocks", [])
        md_lines=[]
        for blk in blocks:
            t = blk.get("t")
            c = blk.get("c")
            if t == "Para":
                txt = ""
                for inline in c:
                    if inline["t"] == "Str":
                        txt += inline["c"] + " "
                    elif inline["t"] == "Space":
                        txt += " "
                md_lines.append(txt.strip())
                md_lines.append("")
            elif t == "Header":
                level = c[0]
                inlines = c[2]
                txt = "".join([x["c"] for x in inlines if x["t"]=="Str"])
                md_lines.append("#"*level + " " + txt)
                md_lines.append("")
        return "\n".join(md_lines).strip() + "\n" if md_lines else "\n"
    except Exception:
        return json_text

def md_to_json(md_text):
    blocks=[]
    parsed = parse_blocks(md_text, smart=False)
    for b in parsed:
        if b["type"]=="header":
            level = b["level"]
            text = b["content"]
            inlines=[]
            for word in text.split():
                inlines.append({"t":"Str","c":word})
                inlines.append({"t":"Space"})
            if inlines and inlines[-1]["t"]=="Space":
                inlines.pop()
            blocks.append({"t":"Header","c":[level, [b["id"] or "", [], []], inlines]})
        elif b["type"]=="para":
            txt = b["text"]
            clean = re.sub(r'\*([^*]+)\*', r'\1', txt)
            words = clean.split()
            inlines=[]
            for w in words:
                inlines.append({"t":"Str","c":w})
                inlines.append({"t":"Space"})
            if inlines and inlines[-1]["t"]=="Space":
                inlines.pop()
            blocks.append({"t":"Para","c": inlines})
        else:
            txt = b.get("text","") or str(b)
            inlines=[{"t":"Str","c":w} for w in txt.split()]
            inlines2=[]
            for idx, inl in enumerate(inlines):
                inlines2.append(inl)
                if idx < len(inlines)-1:
                    inlines2.append({"t":"Space"})
            blocks.append({"t":"Para","c": inlines2})
    data = {"pandoc-api-version":[1,23,1,2],"meta":{},"blocks":blocks}
    return json.dumps(data)

def md_to_native(md_text):
    parsed = parse_blocks(md_text, smart=False)
    parts=[]
    for b in parsed:
        if b["type"]=="header":
            lvl = b["level"]
            txt = b["content"]
            txt_esc = txt.replace('"', '\\"')
            parts.append(f'Header {lvl} ( "{b["id"] or txt.lower()}" , [] , [] ) [ Str "{txt_esc}" ]')
        elif b["type"]=="para":
            txt = b["text"]
            words = txt.split()
            inlines=[]
            for w in words:
                w_clean = re.sub(r'\*([^*]+)\*', r'\1', w)
                w_clean = w_clean.replace('"','\\"')
                inlines.append(f'Str "{w_clean}"')
            inline_str = " , Space , ".join(inlines)
            parts.append(f'Para [ {inline_str} ]')
        else:
            parts.append(f'Para [ Str "{b.get("text","")}" ]')
    return "[ " + "\n, ".join(parts) + "\n]\n" if parts else "[ ]\n"

def md_to_rst(md_text, smart=True):
    parsed = parse_blocks(md_text, smart=smart)
    out=[]
    for b in parsed:
        if b["type"]=="header":
            txt = b["content"]
            lvl = b["level"]
            underline = "=" if lvl==1 else "-" if lvl==2 else "~"
            out.append(txt)
            out.append(underline*len(txt))
            out.append("")
        elif b["type"]=="para":
            out.append(b["text"])
            out.append("")
        elif b["type"]=="ul":
            for it in b["items"]:
                out.append(f"- {it}")
            out.append("")
        elif b["type"]=="ol":
            for idx,it in enumerate(b["items"],1):
                out.append(f"{idx}. {it}")
            out.append("")
        elif b["type"]=="code":
            out.append("::")
            out.append("")
            for line in b["text"].splitlines():
                out.append(f"    {line}")
            out.append("")
        elif b["type"]=="hr":
            out.append("----")
            out.append("")
        else:
            out.append(str(b))
    return "\n".join(out).strip() + "\n" if out else "\n"

